head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > setColumnDisableEdit]<br/>Body Column 정보를 사용하여 특정 Column 의 텍스트 편집을 비활성화할 지 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Column 의 ID 를 설정하여 텍스트 편집의 비활성화 여부를 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_item !== 'undefined') {
        $p.data.remove("dlt_item");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] col1/col3 = inputType=autoComplete(itemSet 라벨=지역명 / 값=코드), col2/col4 = text. Row 4개. autoComplete 컬럼만 setColumnDisableEdit 동작.\n[절차] par_columnInfo(Column ID) / disabled 선택 -> setColumnDisableEdit 실행 -> 해당 컬럼 셀 더블클릭(편집모드) -> 값 입력 시도 -> 다른 곳 클릭(포커스아웃).\n[확인] columnInfo 를 인덱스 대신 Column ID(col1~col4) 로 지정해도 동일 동작. disabled=true 면 입력 텍스트가 셀 값에 반영되지 않고(리스트 선택만) 원래 값 유지, false 면 입력값 반영."', '', 'label1');

    // itemSet 바인딩용 DataList (autoComplete inputType 용 : col1=라벨(지역명), col2=값(코드))
    $c.gcm.createBasicDataList('', '', 'dlt_item');
    dlt_item.setJSON([
        { "col1": "서울", "col2": "01" },
        { "col1": "부산", "col2": "02" },
        { "col1": "대구", "col2": "03" },
        { "col1": "광주", "col2": "04" }
    ]);

    // 본문 데이터리스트 (col1/col3 : autoComplete 코드 저장, col2/col4 : text)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "01", "col2": "H1", "col3": "02", "col4": "메모A" },
        { "col1": "02", "col2": "H2", "col3": "03", "col4": "메모B" },
        { "col1": "03", "col2": "H3", "col3": "01", "col4": "메모C" },
        { "col1": "04", "col2": "H4", "col3": "02", "col4": "메모D" }
    ]);

    // target 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_item"><w2:label ref="col1"></w2:label><w2:value ref="col2"></w2:value></w2:itemset></w2:choices>';
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" editable="true" dataList="data:dlt_bind" id="" ev:onafteredit="scwin.target1_onafteredit" style="width:680px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" inputType="text" id="hcol1" value="col1 (autoComplete)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol2" value="col2 (text)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol3" value="col3 (autoComplete)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="170" inputType="autoComplete" id="col1" dataList="col1">' + itemset + '</w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="170" inputType="autoComplete" id="col3" dataList="col3">' + itemset + '</w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// setColumnDisableEdit 실행 : columnInfo 를 Column ID(문자열)로 그대로 지정하여 텍스트 편집 비활성화 여부를 설정
//  _2 : columnInfo 를 Number 변환하지 않고 Column ID(문자열) 그대로 전달
scwin.btn_setColumnDisableEdit_onclick = function () {
    let columnInfo = par_columnInfo.getValue();
    let disabledBool = (par_disabled.getValue() === "true");

    scwin.target1.setColumnDisableEdit(columnInfo, disabledBool);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setColumnDisableEdit('" + columnInfo + "', " + disabledBool + ") 적용"
        + " | 컬럼 '" + columnInfo + "' 셀 더블클릭 -> 편집모드에서 "
        + (disabledBool ? "텍스트 입력 비활성(리스트 선택만)" : "텍스트 입력 가능")
        + " 확인. 포커스아웃 시 셀 표시값 출력");
}



// 셀 편집모드 종료(포커스아웃) 시 발생. 셀에 표시된 값을 리턴창에 출력한다.
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let colId = scwin.target1.getColumnID(columnIndex);
    let shown = scwin.target1.getCellDisplayData(rowIndex, columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "셀(" + rowIndex + ", " + colId + ") 표시값 : " + shown);
}
